import React, { useEffect, useState } from "react";
import { apiDelete, apiGet } from "../utils/api";
import InvoiceTable from "./InvoiceTable";
import InvoiceFilter from "./InvoiceFilter";
import Pagination from "../components/Pagination";

const InvoiceIndex = () => {
    const [invoices, setInvoices] = useState([]);
    const [filter, setFilter] = useState({ limit: 5, page: 0 });
    const [pendingFilter, setPendingFilter] = useState({ limit: 5, page: 0 }); // Stav pro neuložený filtr
    const [buyerList, setBuyerList] = useState([]);
    const [sellerList, setSellerList] = useState([]);
    const [totalCount, setTotalCount] = useState(0);

    const fetchInvoices = async () => {
        const query = new URLSearchParams(filter).toString();
        const endpoint = `/api/invoices?${query}`;
        const data = await apiGet(endpoint);
        setInvoices(data);
    };

    const fetchInvoiceCount = async () => {
        const query = new URLSearchParams(filter).toString();
        const data = await apiGet(`/api/invoices/count?${query}`);
        setTotalCount(data.count);
    };

    useEffect(() => {
        fetchInvoices();
        fetchInvoiceCount();
        apiGet("/api/persons").then(setSellerList);
        apiGet("/api/persons").then(setBuyerList);
    }, [filter]); // Změna se spustí pouze při změně `filter`, ne `pendingFilter`

    const deleteInvoice = async (id) => {
        try {
            await apiDelete(`/api/invoices/${id}`);
            setInvoices(invoices.filter((item) => item._id !== id));
        } catch (error) {
            console.error(error.message);
            alert(error.message);
        }
    };

    const handleFilterChange = (e) => {
        const { name, value } = e.target;
        setPendingFilter({
            ...pendingFilter,
            [name]: value === "" ? null : isNaN(value) ? value : Number(value),
        });
    };

    const handleFilterSubmit = (e) => {
        e.preventDefault();
        setFilter({ ...pendingFilter, page: 0 }); // Použijeme nový filtr a resetujeme stránkování
    };

    return (
        <div>
            <h1>Seznam faktur</h1>
            <InvoiceFilter
                filter={pendingFilter} // Používáme `pendingFilter`, takže změny se neaplikují ihned
                handleChange={handleFilterChange}
                handleSubmit={handleFilterSubmit}
                confirm="Filtrovat"
                buyerList={buyerList}
                sellerList={sellerList}
            />
            <InvoiceTable deleteInvoice={deleteInvoice} items={invoices} label="" />
            <Pagination filter={filter} setFilter={setFilter} totalCount={totalCount} />
        </div>
    );
};

export default InvoiceIndex;
